// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        uint256 before_totalDistributed = c.totalDistributed();
        uint256 before_totalSupply = c.totalSupply();

        vm.assume(before_totalDistributed <= before_totalSupply);

        bool ok;
        try c.NETM{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 post_bal_owner = c.balanceOf(address(this));
        uint256 post_totalDistributed = c.totalDistributed();

        assertTrue(post_bal_owner == post_totalDistributed);
    }
}
